import { test, expect } from '@playwright/test';

test.describe('Video Captions Accessibility', () => {
  test.beforeEach(async ({ page }) => {
    await page.goto('/videos');
  });

  test('should display captions when video is playing', async ({ page }) => {
    // Locate and click the video element using getByRole
    const video = page.getByRole('button', { name: /play/i });
    await video.click();

    // Wait for video to load
    await page.waitForLoadState('networkidle');

    // Verify video is playing
    const videoElement = page.locator('[data-testid="video-player"]');
    await expect(videoElement).toBeVisible();

    // Locate and click the captions toggle button using getByRole
    const captionsToggle = page.getByRole('button', { name: /captions/i });
    await captionsToggle.click();

    // Verify captions are visible
    const captionsContainer = page.locator('[data-testid="captions-container"]');
    await expect(captionsContainer).toBeVisible();

    // Verify captions text is displayed
    const captionText = page.getByText(/this is a sample video with captions/i);
    await expect(captionText).toBeVisible();

    // Verify captions are styled correctly
    const captionStyle = page.locator('[data-testid="captions-style"]');
    await expect(captionStyle).toHaveCSS('background-color', 'rgba(0, 0, 0, 0.7)');
  });

  test('should hide captions when captions toggle is clicked again', async ({ page }) => {
    // Locate and click the video element using getByRole
    const video = page.getByRole('button', { name: /play/i });
    await video.click();

    // Wait for video to load
    await page.waitForLoadState('networkidle');

    // Locate and click the captions toggle button using getByRole
    const captionsToggle = page.getByRole('button', { name: /captions/i });
    await captionsToggle.click();

    // Verify captions are visible
    const captionsContainer = page.locator('[data-testid="captions-container"]');
    await expect(captionsContainer).toBeVisible();

    // Locate and click the captions toggle button again
    await captionsToggle.click();

    // Verify captions are hidden
    await expect(captionsContainer).not.toBeVisible();

    // Verify captions text is no longer visible
    const captionText = page.getByText(/this is a sample video with captions/i);
    await expect(captionText).not.toBeVisible();
  });
});
